# =============================================================================
# Immich Importer LXC - Photo Import & Cloud Backup
# =============================================================================
# Container ID: 303 (existing)
#
# Run immich-go for Google Photos import, rclone for B2 cloud backup.
# Non-Docker LXC with direct tool installation.
# =============================================================================

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "container_id" {
  type    = number
  default = 303
}

variable "cores" {
  type    = number
  default = 2
}

variable "memory" {
  type    = number
  default = 4096
}

variable "rootfs_size" {
  type    = number
  default = 64
}

variable "swap" {
  type    = number
  default = 512
}

# Backblaze B2 credentials (from 1Password)
variable "b2_account_id" {
  type      = string
  sensitive = true
}

variable "b2_application_key" {
  type      = string
  sensitive = true
}

variable "rclone_crypt_password" {
  type      = string
  sensitive = true
}

variable "rclone_crypt_password2" {
  type      = string
  sensitive = true
}

# Immich configuration
variable "immich_server" {
  type    = string
  default = ""
}

variable "immich_api_key" {
  type      = string
  sensitive = true
}

# Cloud backup schedule
variable "cloud_backup_schedule" {
  type    = string
  default = "0 3 * * 0,3"
}

# iCloud credentials (for icloudpd)
variable "icloud_username" {
  type        = string
  description = "Apple ID email for iCloud Photo download"
}

variable "icloud_password" {
  type        = string
  sensitive   = true
  description = "App-specific password for iCloud (generate at appleid.apple.com)"
}

# iCloud sync schedule (daily at 4 AM, after cloud backup)
variable "icloud_sync_schedule" {
  type    = string
  default = "0 4 * * *"
}

# iCloud download directory
variable "icloud_download_dir" {
  type    = string
  default = "/downloads/icloud"
}

# =============================================================================
# LXC Sidecars Module Variables
# =============================================================================
# This module manages sidecar services for LXC containers:
#   - Backup (proxmox-backup-client with PBS)
#   - Alloy (Grafana Alloy for log/metric collection)
#   - DIUN (Docker image update notifications) - Future
# =============================================================================

# =============================================================================
# Container Information
# =============================================================================

variable "container_id" {
  description = "LXC container ID"
  type        = number
}

variable "container_ip" {
  description = "Container IP address (without CIDR)"
  type        = string
}

variable "container_name" {
  description = "Container hostname"
  type        = string
}

# =============================================================================
# Proxmox SSH Connection (for Ansible deployment)
# =============================================================================

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address"
  type        = string
}

variable "proxmox_ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox host"
  type        = string
}

# =============================================================================
# Backup Configuration
# =============================================================================

variable "backup" {
  description = "Backup configuration for PBS client"
  type = object({
    enabled     = bool
    schedule    = string                    # "daily", "02:00", "Sun 03:00"
    retention   = optional(string, "7")     # Keep N backups
    namespace   = string                    # PBS namespace (usually container name)

    # Pre-backup commands (database dumps, etc.)
    pre_backup_commands = optional(list(object({
      name    = string
      command = string
      timeout = optional(number, 300)
    })), [])

    # Paths to backup/exclude
    include_paths = optional(list(string), ["/config"])
    exclude_paths = optional(list(string), ["/var/lib/docker/overlay2"])

    # PBS server settings
    pbs_server     = optional(string, "10.100.1.102")
    pbs_datastore  = optional(string, "homelab")
    pbs_user       = optional(string, "backup@pbs")
    pbs_password_cmd = optional(string, "op read 'op://homelab/PBS - Proxmox Backup Server/password'")

    # Alert settings
    ntfy_url           = optional(string, "http://10.100.5.100:8080/backup-alerts")
    ntfy_priority      = optional(string, "default")
    ntfy_tags          = optional(string, "backup")
    notify_on_success  = optional(bool, true)   # Send notification on successful backup
    notify_on_failure  = optional(bool, true)   # Send notification on failed backup (recommended: always true)
  })
  default = null

  validation {
    condition = var.backup == null || (
      var.backup.enabled == true && var.backup.namespace != ""
    )
    error_message = "If backup is enabled, namespace must be provided."
  }

  validation {
    condition = var.backup == null || (
      var.backup.schedule == "daily" ||
      can(regex("^[0-9]{2}:[0-9]{2}$", var.backup.schedule)) ||
      can(regex("^(mon|tue|wed|thu|fri|sat|sun) [0-9]{2}:[0-9]{2}$", lower(var.backup.schedule)))
    )
    error_message = "Schedule must be 'daily', 'HH:MM', or 'day HH:MM' (e.g., 'Sun 03:00')."
  }
}

# =============================================================================
# Container Management Agents
# =============================================================================

variable "pulse_agent" {
  description = "Pulse Docker agent configuration for container monitoring"
  type = object({
    enabled     = optional(bool, false)
    pulse_url   = optional(string, "http://10.100.1.104:7655")
    pulse_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.pulse_agent.enabled, false) == false || try(var.pulse_agent.pulse_token, "") != ""
    error_message = "If pulse_agent is enabled, pulse_token must be provided."
  }
}

variable "arcane_agent" {
  description = "Arcane remote agent configuration for container management"
  type = object({
    enabled         = optional(bool, false)
    manager_url     = optional(string, "http://10.100.1.104:3552")
    bootstrap_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.arcane_agent.enabled, false) == false || try(var.arcane_agent.bootstrap_token, "") != ""
    error_message = "If arcane_agent is enabled, bootstrap_token must be provided."
  }
}

# =============================================================================
# Grafana Alloy Agent
# =============================================================================

variable "alloy_agent" {
  description = "Grafana Alloy agent for log/metric collection to Loki/Prometheus"
  type = object({
    enabled        = optional(bool, false)
    loki_url       = optional(string, "https://loki-push.homelab.rambtech.dev")
    prometheus_url = optional(string, "https://prometheus-push.homelab.rambtech.dev")
    username       = optional(string, "")
    password       = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.alloy_agent.enabled, false) == false || (
      try(var.alloy_agent.username, "") != "" && try(var.alloy_agent.password, "") != ""
    )
    error_message = "If alloy_agent is enabled, username and password must be provided for authentication."
  }
}

# =============================================================================
# Future Sidecars (Placeholder)
# =============================================================================

variable "diun_enabled" {
  description = "Enable DIUN for Docker image update notifications"
  type        = bool
  default     = false
}

